input_ids = tokenizer(prompt, return_tensors="pt").input_ids.to(model.device)

allowed_tokens = ["A", "B", "C", "D", "E"]
allowed_token_ids = [tokenizer.convert_tokens_to_ids(token) for token in allowed_tokens]
assert all(tid != tokenizer.unk_token_id for tid in allowed_token_ids), "Some choices not in vocab!"

logits_processors = LogitsProcessorList([ConstrainedLogitsProcessor(allowed_token_ids)])

output = model.generate(
    input_ids,
    max_new_tokens=1,  # Only generate one token (the choice)
    logits_processor=logits_processors,
    do_sample=False,   # Greedy: pick the highest probability among allowed
    pad_token_id=tokenizer.eos_token_id
)

generated_token = tokenizer.decode(output[0][len(input_ids[0]):])
print(f"{generated_token}")